mapper.select:
SELECT d.id AS device_id, d.device_name AS device_name, host(d.ip_address) AS ip_address, i.metric_type AS metric_type, COUNT(i.id) AS total_incidents, COALESCE(SUM(CASE WHEN i.severity = 'WARNING' THEN 1 ELSE 0 END), 0) AS warning_count, COALESCE(SUM(CASE WHEN i.severity = 'CRITICAL' THEN 1 ELSE 0 END), 0) AS critical_count, COALESCE(SUM(CASE WHEN i.status = 'OPEN' THEN 1 ELSE 0 END), 0) AS open_count, COALESCE(SUM(CASE WHEN i.status = 'RESOLVED' THEN 1 ELSE 0 END), 0) AS resolved_count, MAX(i.peak_value) AS max_peak_value, MIN(i.peak_value) AS min_peak_value, AVG(i.peak_value) AS avg_peak_value FROM incidents i INNER JOIN devices d ON d.id = i.device_id WHERE i.created_at >= #{start} AND i.created_at < #{end}
AND i.device_id = #{deviceId}
GROUP BY d.id, d.device_name, d.ip_address, i.metric_type ORDER BY d.device_name ASC, i.metric_type ASC
